#include "stdlib/math/base/special/log2f.h"
#include "stdlib/number/float32/base/to_word.h"
#include "stdlib/number/float32/base/from_word.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/constants/float32/abs_mask.h"
#include "stdlib/constants/float32/significand_mask.h"
#include "stdlib/constants/float32/exponent_bias.h"
#include "stdlib/constants/float32/exponent_mask.h"
#include "stdlib/constants/float32/ninf.h"
#include "stdlib/math/base/special/kernel_log1pf.h"
#include <stdint.h>

// 1 => 0 01111111 00000000000000000000000 => 0x3f800000 = 1065353216
static const int32_t ONE_WORD = 0x3f800000;

// 1.1754943508222875e-38 => 0 00000001 00000000000000000000000 => 0x00800000 = 8388608
static const int32_t MIN_NORM_WORD = 0x00800000;

// Mask to clear lower 12 mantissa bits:
static const int32_t TRUNC_MASK = 0xfffff000;

static const float TWO25 = 3.3554432000e+07;  // 0x4c000000
static const float IVLN2HI = 1.4428710938e+00;  // 0x3fb8b000
static const float IVLN2LO = -1.7605285393e-04;  // 0xb9389ad4

/**
* Evaluates the binary logarithm (base two) of a single-precision floating-point number.
*
* @param x    input value
* @return     output value
*
* @example
* float out = stdlib_base_log2f( 4.0f );
* // returns 2.0f
*/
float stdlib_base_log2f( const float x ) {
	float valLo;
	float valHi;
	uint32_t hx;
	int32_t ihx;
	float hfsq;
	float hi;
	int32_t i;
	int32_t k;
	float lo;
	float xc;
	float f;
	float R;
	float w;
	float y;

	if ( stdlib_base_is_nanf( x ) || x < 0.0 ) {
		return 0.0f / 0.0f; // NaN
	}
	xc = x;
	stdlib_base_float32_to_word( x, &hx );
	ihx = (int32_t)hx;
	k = 0;
	if ( ihx < MIN_NORM_WORD ) {
		// Case: x < 2**-126
		if ( ( ihx & STDLIB_CONSTANT_FLOAT32_ABS_MASK ) == 0 ) {
			return STDLIB_CONSTANT_FLOAT32_NINF;
		}
		k -= 25;

		// Subnormal number, scale up x:
		xc *= TWO25;
		stdlib_base_float32_to_word( xc, &hx );
		ihx = (int32_t)hx;
	}
	if ( ihx >= STDLIB_CONSTANT_FLOAT32_EXPONENT_MASK ) {
		return xc + xc;
	}
	// Case: log(1) = +0
	if ( ihx == ONE_WORD  ) {
		return 0;
	}
	k += ( ( ihx>>23 ) - STDLIB_CONSTANT_FLOAT32_EXPONENT_BIAS );
	ihx &= STDLIB_CONSTANT_FLOAT32_SIGNIFICAND_MASK;
	i = ( ihx+0x4afb0d ) & MIN_NORM_WORD ;

	// Normalize x or x/2...
	stdlib_base_float32_from_word( (uint32_t)( ihx|( i^ONE_WORD ) ), &xc );
	k += (i>>23);
	y = (float)k;
	f = xc - (float)1.0;
	hfsq = (float)0.5 * f * f;
	R = stdlib_base_kernel_log1pf( f );
	if ( sizeof( float_t ) > sizeof( float ) )
		return (R - hfsq + f) * ((float_t)IVLN2LO + IVLN2HI) + y;

	hi = f - hfsq;
	stdlib_base_float32_to_word( hi, &ihx );
	stdlib_base_float32_from_word( (uint32_t)( ihx & TRUNC_MASK ) , &hi );
	lo = ( f - hi ) - hfsq + R;
	valLo = hi * IVLN2HI;
	valHi = ( ( lo + hi ) * IVLN2LO ) + ( lo * IVLN2HI );

	w = y + valLo;
	valHi += ( y - w ) + valLo;
	valLo = w;

	return valHi + valLo;
}
